"use client";
import React, { useEffect } from "react";
import { getCarrito } from "../Data/Cart";

interface Product {
  id: number;
  name: string;
  price: number;
  imageUrl: string;
  code: string;
}

interface NewProductsContainerProps {
  products: Product[];
  setItemQuantity: React.Dispatch<React.SetStateAction<number>>;
  handleAddProduct: (productCode: string) => void;
  handleDeleteProduct: (productCode: string) => void;
}

const NewProductsContainer: React.FC<NewProductsContainerProps> = ({
  products,
  setItemQuantity,
  handleAddProduct,
  handleDeleteProduct,
}) => {
  const handleAddToCart = (productCode: string) => {
    handleAddProduct(productCode);
    updateItemQuantity();
  };

  const handleRemoveFromCart = (productCode: string) => {
    handleDeleteProduct(productCode);
    updateItemQuantity();
  };

  const updateItemQuantity = () => {
    const totalQuantity = getCarrito().reduce(
      (sum, product) => sum + product.quantity,
      0
    );
    setItemQuantity(totalQuantity);
  };

  useEffect(() => {
    updateItemQuantity();
  }, []);

  return (
    <div>
      <h2>Productos</h2>
      {products.map((product) => (
        <div key={product.id}>
          <img src={product.imageUrl} alt={product.name} />
          <h3>{product.name}</h3>
          <p>Precio: ${product.price}</p>
          <button onClick={() => handleAddToCart(product.code)}>
            Agregar al carrito
          </button>
          <button onClick={() => handleRemoveFromCart(product.code)}>
            Eliminar del carrito
          </button>
        </div>
      ))}
    </div>
  );
};

export default NewProductsContainer;
